using System.ComponentModel;
namespace LadderRecords;
record RegisteredRecord(Selection Chart,string SongName,string Artist,decimal Accuracy,int? PlayCount,DateTime? LastPlayedAt,int RawScore=0){public int Button=>Chart.Button;public string Pattern=>Chart.Pattern;public string Judge=>Chart.Judge;}
static class RecordRows
{
 public static List<RegisteredRecord> Read(Catalog catalog,Profile profile){var songs=catalog.Songs.ToDictionary(s=>s.Id);var rows=new List<RegisteredRecord>();foreach(var (key,score) in profile.Records){var parts=key.Split('|');if(parts.Length!=4||!int.TryParse(parts[1],out int button))continue;songs.TryGetValue(parts[0],out var song);rows.Add(new(new(parts[0],button,parts[2],parts[3],1),song?.Name??$"곡 정보 없음 ({parts[0]})",song?.Artist??"",score.Accuracy,score.PlayCount,score.LastPlayedAt?.ToLocalTime(),score.Value));}return rows;}
 public static IEnumerable<RegisteredRecord> Filter(IEnumerable<RegisteredRecord> rows,string query,int? button,string pattern,string judge){var words=query.Split(' ',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);return rows.Where(r=>(button==null||r.Chart.Button==button)&&(pattern=="전체"||r.Chart.Pattern==pattern)&&(judge=="전체"||(judge=="하드·맥스"?r.Chart.Judge is "하드" or "맥스":r.Chart.Judge==judge))&&words.All(word=>(r.SongName+" "+r.Artist).Contains(word,StringComparison.OrdinalIgnoreCase)));}
}
static class RecordOrdering
{
 public static void Apply(List<RegisteredRecord> list,string column,ListSortDirection order){
  list.Sort((a,b)=>{int value=column switch{"Song"=>StringComparer.CurrentCultureIgnoreCase.Compare(a.SongName,b.SongName),"Artist"=>StringComparer.CurrentCultureIgnoreCase.Compare(a.Artist,b.Artist),"Button"=>a.Button.CompareTo(b.Button),"Pattern"=>string.CompareOrdinal(a.Pattern,b.Pattern),"Judge"=>string.CompareOrdinal(a.Judge,b.Judge),"Accuracy"=>a.Accuracy.CompareTo(b.Accuracy),"RawScore"=>a.RawScore.CompareTo(b.RawScore),"PlayCount"=>Nullable.Compare(a.PlayCount,b.PlayCount),"LastPlayedAt"=>Nullable.Compare(a.LastPlayedAt,b.LastPlayedAt),_=>0};if(value!=0)return order==ListSortDirection.Ascending?value:-value;int name=StringComparer.CurrentCultureIgnoreCase.Compare(a.SongName,b.SongName);if(name!=0)return name;return string.CompareOrdinal(a.Chart.Key,b.Chart.Key);});
 }
}
class RecordsView:ListView
{
 IReadOnlyList<RegisteredRecord> records=Array.Empty<RegisteredRecord>();readonly Dictionary<int,ListViewItem> cache=new();readonly Dictionary<(string Text,int Height,int MaxWidth,int Dpi),Bitmap> badgeCache=new();readonly Font badgeFont=Theme.Px("맑은 고딕",9,FontStyle.Bold);readonly ImageList spacing=new(){ImageSize=new(1,32)};
 public ColumnHeader? SortedColumn{get;private set;}
 public SortOrder SortOrder{get;private set;}
 public int RowCount=>VirtualListSize;
 public event Action<ColumnHeader,ListSortDirection>? OrderChanged;
 public RecordsView(){View=View.Details;VirtualMode=true;OwnerDraw=true;FullRowSelect=true;MultiSelect=false;GridLines=false;HideSelection=false;DoubleBuffered=true;spacing.Images.Add(new Bitmap(1,1));SmallImageList=spacing;
  RetrieveVirtualItem+=(_,e)=>{if(!cache.TryGetValue(e.ItemIndex,out var item)){var row=ItemAt(e.ItemIndex);item=row==null?new ListViewItem(""):new ListViewItem(new[]{row.SongName,row.Artist,$"{row.Button}B",row.Pattern,row.Judge,$"{row.Accuracy:F2}%",$"{row.RawScore:N0}",row.PlayCount is int count?$"{count}회":"",row.LastPlayedAt?.ToString("yyyy-MM-dd HH:mm:ss")??""}){ImageIndex=0};cache[e.ItemIndex]=item;}e.Item=item;};
  DrawColumnHeader+=(_,e)=>{using(var back=new SolidBrush(Theme.Side))e.Graphics.FillRectangle(back,e.Bounds);using(var line=new Pen(Theme.Line))e.Graphics.DrawLine(line,e.Bounds.Left,e.Bounds.Bottom-1,e.Bounds.Right,e.Bounds.Bottom-1);using var bold=Theme.Px(Font.FontFamily.Name,9.5f,FontStyle.Bold);var flags=TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix|(e.Header!.TextAlign==HorizontalAlignment.Right?TextFormatFlags.Right:TextFormatFlags.Left);TextRenderer.DrawText(e.Graphics,e.Header.Text,bold,Rectangle.Inflate(e.Bounds,-6,0),e.Header==SortedColumn?Theme.Accent:Theme.Dim,flags);};
  DrawItem+=(_,e)=>{if(View!=View.Details)e.DrawDefault=true;};
  DrawSubItem+=(_,e)=>{if(e.Item==null||e.SubItem==null)return;bool selected=e.Item.Selected;using(var brush=new SolidBrush(selected?Theme.Select:Theme.Field))e.Graphics.FillRectangle(brush,e.Bounds);using(var line=new Pen(Theme.Line))e.Graphics.DrawLine(line,e.Bounds.Left,e.Bounds.Bottom-1,e.Bounds.Right,e.Bounds.Bottom-1);string text=e.SubItem.Text;if(e.ColumnIndex is 2 or 3 or 4){var badge=BadgeImage(text,e.Bounds.Height-6,e.Bounds.Width-8,(int)e.Graphics.DpiX);e.Graphics.DrawImageUnscaled(badge,e.Bounds.X+(e.Bounds.Width-badge.Width)/2,e.Bounds.Y+3);}else{var flags=TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix;if(e.ColumnIndex is 5 or 6 or 7)flags|=TextFormatFlags.Right;TextRenderer.DrawText(e.Graphics,text,Font,Rectangle.Inflate(e.Bounds,-4,0),Theme.Text,flags);}};
  ColumnClick+=(_,e)=>{var column=Columns[e.Column];Sort(column.Name??"Song",SortedColumn==column&&SortOrder==System.Windows.Forms.SortOrder.Ascending?ListSortDirection.Descending:ListSortDirection.Ascending);};
 }
 Bitmap BadgeImage(string text,int height,int maxWidth,int dpi){var key=(text,height,maxWidth,dpi);if(badgeCache.TryGetValue(key,out var cached))return cached;int width=Math.Max(1,Math.Min(maxWidth,TextRenderer.MeasureText(text,badgeFont).Width+14));var image=new Bitmap(width,Math.Max(1,height),System.Drawing.Imaging.PixelFormat.Format32bppPArgb);image.SetResolution(dpi,dpi);using(var graphics=Graphics.FromImage(image))Theme.DrawBadge(graphics,text,badgeFont,new RectangleF(0,0,image.Width-1,image.Height-1));badgeCache[key]=image;return image;}
 void ClearBadgeCache(){foreach(var image in badgeCache.Values)image.Dispose();badgeCache.Clear();}
 protected override void OnColumnWidthChanged(ColumnWidthChangedEventArgs e){ClearBadgeCache();base.OnColumnWidthChanged(e);}
 public RegisteredRecord? ItemAt(int index)=>index>=0&&index<records.Count?records[index]:null;
 public RegisteredRecord? SelectedRecord=>SelectedIndices.Count==1?ItemAt(SelectedIndices[0]):null;
 public void SelectIndex(int index){if(index<0||index>=RowCount)return;SelectedIndices.Clear();SelectedIndices.Add(index);EnsureVisible(index);}
 // 창을 없애기 직전에 목록을 비운다. 접근성 클라이언트(화면 읽기, 화면 조작 도구 등)가 줄을 읽어 간 적이 있으면 WinForms 가 목록을 없앨 때
 // 줄마다 접근성 정보를 끊는데, 3,200줄에 83 ~ 115초가 걸려 프로그램이 그만큼 늦게 끝났다. 줄이 없으면 끊을 것도 없다(0.14초). docs\기록\개발용검사.md
 internal void ReleaseRows(){if(IsDisposed||!IsHandleCreated||VirtualListSize==0)return;Display(Array.Empty<RegisteredRecord>());}
 public void Display(IReadOnlyList<RegisteredRecord> rows){BeginUpdate();try{SelectedIndices.Clear();records=rows;cache.Clear();VirtualListSize=rows.Count;}finally{EndUpdate();}Invalidate();}
 public void Sort(string name,ListSortDirection order){SortedColumn=Columns[name];SortOrder=order==ListSortDirection.Ascending?System.Windows.Forms.SortOrder.Ascending:System.Windows.Forms.SortOrder.Descending;foreach(ColumnHeader column in Columns)column.Text=column.Text.TrimEnd(' ','▲','▼')+(column==SortedColumn?(order==ListSortDirection.Ascending?" ▲":" ▼"):"");OrderChanged?.Invoke(SortedColumn!,order);}
 protected override void Dispose(bool disposing){if(disposing){ClearBadgeCache();badgeFont.Dispose();spacing.Dispose();}base.Dispose(disposing);}
}
class RecordsDialog:AppWindow
{
 readonly Catalog catalog;readonly RecordStore store;readonly string profileId;readonly string? settingsPath;bool settingsReady;List<RegisteredRecord> displayedRows=new(),allRows=new();long loadedRevision=-1;readonly System.Windows.Forms.Timer refreshTimer=new(){Interval=250};
