 protected override void Dispose(bool disposing){if(disposing){SaveViewSettings();settingsReady=false;refreshTimer.Dispose();grid.ReleaseRows();}base.Dispose(disposing);}
 readonly TextBox search=new(){Width=210};readonly ComboBox button=new ThemedCombo(),pattern=new ThemedCombo(),judge=new ThemedCombo();readonly RecordsView grid=new(){Dock=DockStyle.Fill};readonly Label summary=new(){AutoSize=true,Margin=new(3,8,20,0),Tag="dim"};
 public RecordsDialog(Catalog catalog,RecordStore store,string? settingsPath=null){
  this.catalog=catalog;this.store=store;this.settingsPath=settingsPath;profileId=store.Active.Id;Text="등록한 기록 보기 · "+store.Active.Name;Font=Theme.Px("맑은 고딕",10);ClientSize=new(1160,560);MinimumSize=new(920,400);StartPosition=FormStartPosition.CenterParent;
  var root=new TableLayoutPanel(){Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new(12)};root.RowStyles.Add(new(SizeType.AutoSize));root.RowStyles.Add(new(SizeType.Percent,100));root.RowStyles.Add(new(SizeType.AutoSize));Controls.Add(root);
  var filters=new FlowLayoutPanel(){AutoSize=true,Dock=DockStyle.Fill,WrapContents=true,Margin=new(0,0,0,10)};
  void Add(string name,Control control){filters.Controls.Add(new Label(){Text=name,AutoSize=true,Margin=new(3,7,3,0),Tag="dim"});filters.Controls.Add(control);}
  Add("검색",search);foreach(var c in new[]{button,pattern,judge}){c.DropDownStyle=ComboBoxStyle.DropDownList;c.Width=c==pattern?115:c==judge?110:85;}
  button.Items.AddRange(new object[]{"전체","4B","5B","6B","8B"});pattern.Items.AddRange(new object[]{"전체","NORMAL","HARD","MAXIMUM","SC"});judge.Items.AddRange(new object[]{"전체","노말","하드","맥스","하드·맥스"});foreach(var c in new[]{button,pattern,judge})c.SelectedIndex=0;
  Add("버튼",button);Add("난이도",pattern);Add("판정",judge);var reset=new Button(){Text="초기화",AutoSize=true};reset.Click+=(_,_)=>{search.Clear();foreach(var c in new[]{button,pattern,judge})c.SelectedIndex=0;};filters.Controls.Add(reset);root.Controls.Add(filters,0,0);
  foreach(var column in new[]{("Song","곡명",240),("Artist","아티스트",165),("Button","버튼",65),("Pattern","난이도",115),("Judge","판정",80),("Accuracy","최고 점수 (%)",115),("RawScore","최고 스코어",110),("PlayCount","플레이 카운트",125),("LastPlayedAt","최근 플레이",190)})grid.Columns.Add(new ColumnHeader(){Name=column.Item1,Text=column.Item2,Width=column.Item3,TextAlign=column.Item1 is "Accuracy" or "RawScore" or "PlayCount"?HorizontalAlignment.Right:HorizontalAlignment.Left});
  grid.DoubleClick+=(_,_)=>EditSelected();grid.OrderChanged+=(column,direction)=>{var selected=grid.SelectedRecord?.Chart.Key;RecordOrdering.Apply(displayedRows,column.Name??"Song",direction);grid.Display(displayedRows);int index=selected==null?-1:displayedRows.FindIndex(r=>r.Chart.Key==selected);if(index>=0)grid.SelectIndex(index);else if(grid.RowCount>0)grid.SelectIndex(0);};root.Controls.Add(grid,0,1);
  var footer=new FlowLayoutPanel(){AutoSize=true,Dock=DockStyle.Fill,WrapContents=true,Margin=new(0,10,0,0)};footer.Controls.Add(summary);var edit=new Button(){Text="선택 기록 수정",AutoSize=true};edit.Click+=(_,_)=>EditSelected();var close=new Button(){Text="닫기",AutoSize=true,DialogResult=DialogResult.Cancel};close.Click+=(_,_)=>Close();var delete=new Button(){Text="선택 기록 삭제",AutoSize=true};delete.Click+=(_,_)=>DeleteSelected();footer.Controls.AddRange(new Control[]{edit,delete,close});root.Controls.Add(footer,0,2);CancelButton=close;
  LoadViewSettings();settingsReady=true;FormClosing+=(_,_)=>SaveViewSettings();
  search.TextChanged+=(_,_)=>RefreshRows();foreach(var c in new[]{button,pattern,judge})c.SelectedIndexChanged+=(_,_)=>RefreshRows();refreshTimer.Tick+=(_,_)=>{if(loadedRevision!=store.Revision)RefreshRows();};VisibleChanged+=(_,_)=>refreshTimer.Enabled=Visible;RefreshRows();
 }
 void LoadViewSettings(){var settings=RecordsViewSettings.Load(settingsPath);search.Text=settings.Search??"";void Select(ComboBox combo,string? value){combo.SelectedItem=combo.Items.Contains(value??"")?value:"전체";}Select(button,settings.Button);Select(pattern,settings.Pattern);Select(judge,settings.Judge);foreach(ColumnHeader column in grid.Columns)if(settings.ColumnWidths?.TryGetValue(column.Name!,out int width)==true)column.Width=Math.Clamp(width,40,2000);if(settings.Width>0&&settings.Height>0){var area=Screen.FromControl(this).WorkingArea;Size=new(Math.Clamp(settings.Width,MinimumSize.Width,Math.Max(MinimumSize.Width,area.Width)),Math.Clamp(settings.Height,MinimumSize.Height,Math.Max(MinimumSize.Height,area.Height)));}grid.Sort(grid.Columns.ContainsKey(settings.SortColumn??"")?settings.SortColumn!:"LastPlayedAt",settings.Descending?ListSortDirection.Descending:ListSortDirection.Ascending);}
 void SaveViewSettings(){if(!settingsReady||settingsPath==null)return;try{var size=WindowState==FormWindowState.Normal?Size:RestoreBounds.Size;new RecordsViewSettings(){Search=search.Text,Button=button.Text,Pattern=pattern.Text,Judge=judge.Text,SortColumn=grid.SortedColumn?.Name??"LastPlayedAt",Descending=grid.SortOrder!=SortOrder.Ascending,Width=size.Width,Height=size.Height,ColumnWidths=grid.Columns.Cast<ColumnHeader>().ToDictionary(c=>c.Name!,c=>c.Width)}.Save(settingsPath);}catch(Exception e){summary.Text="목록 설정 저장 실패: "+e.Message;}}
 void RefreshRows(){var active=store.Data.Profiles.Single(p=>p.Id==profileId);if(loadedRevision!=store.Revision){allRows=RecordRows.Read(catalog,active);loadedRevision=store.Revision;}var rows=allRows;Text="등록한 기록 보기 · "+active.Name;int? selectedButton=button.SelectedIndex==0?null:int.Parse(button.Text.TrimEnd('B'));string sort=grid.SortedColumn?.Name??"LastPlayedAt";var direction=grid.SortedColumn==null||grid.SortOrder==SortOrder.Descending?ListSortDirection.Descending:ListSortDirection.Ascending;displayedRows=RecordRows.Filter(rows,search.Text,selectedButton,pattern.Text,judge.Text).ToList();grid.Sort(sort,direction);summary.Text=$"프로필: {active.Name} · {displayedRows.Count} / {rows.Count}개";}
 internal bool DeleteSelected(Func<RegisteredRecord,bool>? confirm=null){if(grid.SelectedRecord is not RegisteredRecord entry)return false;try{if(store.Active.Id!=profileId)throw new Exception("목록을 닫고 현재 프로필에서 다시 열어 주세요.");bool accepted;if(confirm!=null)accepted=confirm(entry);else{using var dialog=new DeleteRecordDialog(entry);accepted=dialog.ShowDialog(this)==DialogResult.OK;}if(!accepted)return false;var current=store.Get(entry.Chart);if(current==null||current.Accuracy!=entry.Accuracy||current.PlayCount!=entry.PlayCount){RefreshRows();throw new Exception("확인하는 동안 이 기록이 바뀌었습니다. 목록에서 다시 확인해 주세요.");}store.DeleteRecord(entry.Chart);RefreshRows();return true;}catch(Exception e){NoticeDialog.Show(this,"기록 삭제",e.Message);return false;}}
 void EditSelected(){if(grid.SelectedRecord is not RegisteredRecord entry)return;try{if(store.Active.Id!=profileId)throw new Exception("목록을 닫고 현재 프로필에서 다시 열어 주세요.");if(!catalog.Songs.Any(s=>s.Id==entry.Chart.SongId&&s.Charts.Contains(new(entry.Chart.Button,entry.Chart.Pattern))))throw new Exception("현재 곡 데이터에서 확인되지 않는 채보입니다.");using var dialog=new RecordDialog(catalog,store,entry.Chart);if(dialog.ShowDialog(this)==DialogResult.OK){store.SetManual(dialog.Chart,dialog.Value,dialog.PlayCount,rawScore:dialog.RawScore);RefreshRows();}}catch(Exception e){NoticeDialog.Show(this,"기록 수정",e.Message);}}
}
